/**
 * Writes the given rows to a CSV file on disk.
 * @param {string} filePath - where to write the file.
 * @returns {number} the number of rows written.
 */
function writeCsv(filePath, rows) {
  fs.writeFileSync(filePath, rows.map(r => r.join(',')).join('\n'));
  return rows.length;
}

